create extension if not exists pgcrypto;
create table if not exists public.family_workspaces(id uuid primary key default gen_random_uuid(),baby_name text not null,stage text not null check(stage in('pregnant','born')),important_date date not null,owner_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.family_members(workspace_id uuid references public.family_workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,display_name text not null,role text not null check(role in('owner','collaborator')),created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table if not exists public.family_invites(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.family_workspaces(id) on delete cascade,token text not null unique,pin_hash text not null,expires_at timestamptz not null,used_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
alter table public.family_workspaces enable row level security;alter table public.family_members enable row level security;alter table public.family_invites enable row level security;
create or replace function public.is_family_member(p_workspace_id uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from family_members where workspace_id=p_workspace_id and user_id=auth.uid())$$;
create policy "members read workspace" on public.family_workspaces for select using(public.is_family_member(id));
create policy "members read members" on public.family_members for select using(public.is_family_member(workspace_id));
create or replace function public.create_family_workspace(p_baby_name text,p_stage text,p_date date,p_display_name text) returns uuid language plpgsql security definer set search_path=public as $$declare wid uuid;begin if auth.uid() is null then raise exception '로그인이 필요합니다.';end if;insert into family_workspaces(baby_name,stage,important_date,owner_id)values(p_baby_name,p_stage,p_date,auth.uid())returning id into wid;insert into family_members values(wid,auth.uid(),p_display_name,'owner',now());return wid;end$$;
create or replace function public.create_family_invite(p_workspace_id uuid) returns table(token text,pin text,expires_at timestamptz) language plpgsql security definer set search_path=public as $$declare raw_token text:=encode(gen_random_bytes(24),'hex');raw_pin text:=lpad((floor(random()*1000000))::int::text,6,'0');expiry timestamptz:=now()+interval '24 hours';begin if not exists(select 1 from family_members where workspace_id=p_workspace_id and user_id=auth.uid() and role='owner')then raise exception '초대 권한이 없습니다.';end if;insert into family_invites(workspace_id,token,pin_hash,expires_at,created_by)values(p_workspace_id,raw_token,crypt(raw_pin,gen_salt('bf')),expiry,auth.uid());return query select raw_token,raw_pin,expiry;end$$;
create or replace function public.accept_family_invite(p_token text,p_pin text,p_display_name text) returns uuid language plpgsql security definer set search_path=public as $$declare inv family_invites%rowtype;begin if auth.uid() is null then raise exception '로그인이 필요합니다.';end if;select * into inv from family_invites where token=p_token for update;if inv.id is null or inv.used_at is not null or inv.expires_at<now() then raise exception '만료되었거나 유효하지 않은 초대입니다.';end if;if crypt(p_pin,inv.pin_hash)<>inv.pin_hash then raise exception 'PIN이 올바르지 않습니다.';end if;insert into family_members(workspace_id,user_id,display_name,role)values(inv.workspace_id,auth.uid(),p_display_name,'collaborator')on conflict(workspace_id,user_id)do update set display_name=excluded.display_name;update family_invites set used_at=now() where id=inv.id;return inv.workspace_id;end$$;
revoke all on function public.create_family_workspace(text,text,date,text) from public;revoke all on function public.create_family_invite(uuid) from public;revoke all on function public.accept_family_invite(text,text,text) from public;grant execute on function public.create_family_workspace(text,text,date,text),public.create_family_invite(uuid),public.accept_family_invite(text,text,text) to authenticated;
